ROOT=Path(__file__).resolve().parents[1]
def write(name,text):
 p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text.rstrip()+"\n")
def dump(name,obj):write(name,json.dumps(obj,indent=2)+'\n')
BASE=json.loads((ROOT/'product-baseline/specification.json').read_text())
REQ={r['id']:r for s in BASE['sections'] for r in s['requirements']}
ACC={a['id']:a for a in BASE['acceptance']}
REQ['R002']={**REQ['R002'],'text':'OpenSpec capability requirements and scenarios are the maintained target authority in this new repository. product-baseline is an immutable imported source snapshot; execution/tasks.json defines task metadata, never competing behavior. Update the affected OpenSpec requirements and scenarios before behavior changes. Generated OpenAPI and maintained AsyncAPI implement the contract requirements; do not maintain handwritten OpenAPI. Screenshots guide visual direction, never prove execution.'}
