def refs(s,prefix):
 return [f'{prefix}{int(x):03d}' if prefix=='R' else f'{prefix}{int(x):02d}' for x in s.split(',') if x]
def add(n,title,kind,deps,rs,acs,paths,locks,tests,deliverables,browser=False):
 num=1+sum(t['change']==CHANGES[n-1] for t in TASKS);tid=f'T{n:04d}-{num:03d}'
