# Expand each ticket with deterministic file/test artifacts; their test selectors are contracts to create, not claims of existence.
for t in TASKS:
 if t['id'] in {'T0005-002','T0006-002','T0006-005'}:t['requirements'].append('AI001')
 for c in t['checks']:
  if c['adapter']=='vitest':
   target=UI+c['selector']
   if target not in t['write_paths']:t['write_paths'].append(target)
  if c['adapter']=='maven':
   target=TEST+c['selector']+'.java'
   if target not in t['write_paths']:t['write_paths'].append(target)
 if t['browser_required']:
  t['write_paths'] += [t['browser_charter'],f'quality/e2e/{t["id"]}/**']
 # Readiness tasks are computed batch boundaries; ordinary task claims cannot satisfy them by self-report.
 t['required_stages']=['environment'] if t['kind']=='readiness' else ['environment','developer','static','code_review','tests','test_review','browser','browser_review','integration']
 t['browser_policy']='required' if t['browser_required'] else 'technical charter review; no user-visible change is authorized'
 t['migration_prefix']='1'+t['change'][:4]+'-'+t['id'] if 'schema' in t['exclusive_resources'] else None
 t['read_first']=['AGENTS.md',f'openspec/changes/{t["change"]}/proposal.md',f'openspec/changes/{t["change"]}/design.md',f'openspec/changes/{t["change"]}/specs/{CAPS[CHANGES.index(t["change"])]}/spec.md','docs/execution/handoffs.md','docs/architecture.md','docs/contracts-and-data.md']
 t['prohibited_changes']=['historical applied migration edits','secrets or production data','source repositories outside this new checkout','unrequested features','unapproved dependency/framework changes']
dump('execution/tasks.json',{'schema':1,'tasks':TASKS})
write('openspec/config.yaml','schema: spec-driven\ncontext: |\n  Stone Shelter local release. English artifacts. Generated OpenAPI; maintained AsyncAPI.\n  This is an application seed plus proposed target changes, not implemented acceptance.\n  Read AGENTS.md and execution/tasks.json. Spring AI owns inference, embeddings and RAG.\n  Use deterministic gates and isolated task worktrees. No board integration.\n')
for i,change in enumerate(CHANGES,1):
 cap=CAPS[i-1];ts=[t for t in TASKS if t['change']==change]
 write(f'openspec/changes/{change}/.openspec.yaml','schema: spec-driven\ncreated: 2026-10-24\n')
 write(f'openspec/changes/{change}/proposal.md',f'# {change}\n\n## Why\nImplement work package W{i:02d} of the consolidated product baseline using the inherited application seed; historical completion is not current acceptance.\n\n## What Changes\n'+''.join('- '+t['title']+'\n' for t in ts[1:])+f'\n## Capabilities\n\n### New Capabilities\n- `{cap}`: target release behavior described in the capability spec\n\n## Impact\nApplication modules, generated API, focused tests and independent delivery gates according to execution/tasks.json. No existing sibling project is writable.\n')
 spec='## ADDED Requirements\n\n'
 for rid,r in REQ.items():
  if OWNERS[rid]!=i:continue
  spec+=f'### Requirement: {rid} {r["title"]}\nThe system SHALL enforce the {r["title"].lower()} contract and all scenarios below.\n\n#### Scenario: {rid} behavioral boundaries\n- **WHEN** the {r["title"].lower()} capability is exercised\n- **THEN** {r["text"]}\n\n'
  matches=[a for a in ACC.values() if rid in a['requirements']]
  for a in matches:
   spec+=f'#### Scenario: {a["id"]} / {rid} — {a["title"]}\n- **GIVEN** {a["given"]}\n- **WHEN** {a["when"]}\n- **THEN** {a["then"]}\n\n'
 if i==6:
  spec+='### Requirement: AI001 Framework-native inference and retrieval\nThe application SHALL use Spring AI ChatClient, EmbeddingModel, PgVectorStore and RetrievalAugmentationAdvisor for LLM search and RAG, preserving domain admission and evidence checks.\n\n#### Scenario: AI001 Framework boundary\n- **WHEN** architecture tests inspect the migrated provider, embedding and retrieval components\n- **THEN** inference and retrieval use Spring AI APIs, model counts and deadlines remain enforced, and raw provider HTTP or SQL similarity bypasses fail the gate\n'
 write(f'openspec/changes/{change}/specs/{cap}/spec.md',spec)
 write(f'openspec/changes/{change}/tasks.md','# Implementation tasks\n\nThe first task is readiness for the selected batch. Checkboxes change only after verified integration; they start unchecked. Details are in the linked execution packets.\n\n'+''.join(f'- [ ] {t["id"]} {t["title"]} ([packet](../../../execution/tickets/{t["id"]}.md))\n' for t in ts))
 write(f'openspec/changes/{change}/design.md',f'# Design: {change}\n\n## Context\nRead docs/architecture.md and docs/adr/0001-execution-authority.md. Use the copied implementation as a seed to reconcile against the target; retain correct behavior and replace conflicting behavior.\n\n## Decisions\n'+''.join(f'- **{t["id"]}:** '+ '; '.join(t['deliverables'])+'\n' for t in ts)+f'\n## Contract ownership\nGenerated OpenAPI is the HTTP wire contract. Contract-changing backend tickets merge before dependent frontend work. AsyncAPI is authored before Kafka changes. Shared-file locks and dependencies in execution/tasks.json are mandatory.\n\n## Risks and verification\nNo old PASS is transferable. Scope checks, immutable candidates, monitored focused tests and real-browser reviews follow docs/execution/handoffs.md. Missing test selector or charter assertions block the ticket.\n')
for t in TASKS:
 write(f'execution/tickets/{t["id"]}.md',f'# {t["id"]}: {t["title"]}\n\nStatus: PLANNED — no implementation has been accepted.\n\nChange: `{t["change"]}`; kind: `{t["kind"]}`\n\n## Inputs\n'+''.join('- `'+p+'`\n' for p in t['read_first'])+'\nRequirements: '+', '.join(t['requirements'])+'\n\nAcceptance: '+', '.join(t['acceptance'])+'\n\nDepends on integrated DONE: '+(', '.join(t['depends_on']) or 'none')+'\n\n## Deliverables\n'+''.join('- '+s+'\n' for s in t['deliverables'])+'\n## Write allowlist\n'+''.join('- `'+s+'`\n' for s in t['write_paths'])+'\nExclusive resources: '+(', '.join(t['exclusive_resources']) or 'none')+'\n\n## Focused verification\n'+''.join('- '+c['adapter']+': `'+c['selector']+'`\n' for c in t['checks'])+'\nNew selectors are required deliverables, not pre-existing tests. Missing/empty/skipped results fail closed. Run checks through tools/orchestrate.py, not an unmonitored test command.\n\nBrowser: '+t['browser_policy']+'\n\n## Done\n'+t['completion']+'\n\n## Stop conditions\nOutside allowlist, blocked readiness, new framework without approval, changed shared contract, failed evidence or unowned resource: report the exact finding and return to the coordinator. Do not claim completion or widen scope.\n')
# Full parallel map produced from dependencies, not a second task schedule.
remaining={t['id']:t for t in TASKS};done=set();waves=[]
while remaining:
 wave=[tid for tid,t in remaining.items() if set(t['depends_on'])<=done]
 if not wave:raise SystemExit('Dependency cycle')
 waves.append(wave);done.update(wave)
 for tid in wave:remaining.pop(tid)
dump('execution/dependency-waves.json',{'meaning':'Dependency-ready candidates; resource/write conflicts can reduce simultaneous execution. No task is already done.','waves':waves})
write('docs/execution/parallel-map.md','# Parallel map\n\nDependency readiness is necessary but not sufficient: the coordinator also claims exclusive resources and verifies allowed paths. All backend changes conservatively share api-source; frontend ui-source is independent. This deliberately permits backend/frontend/test-review pipelines without promising collision-free simultaneous edits to the shared Java model. Read-only reviews of frozen candidates may overlap any independent developer. Model qualification has a single model-runtime lease.\n\n```mermaid\nflowchart TD\n'+''.join('  '+t['id'].replace('-','_')+'["'+t['id']+' '+t['kind']+'"]\n'+''.join('  '+d.replace('-','_')+' --> '+t['id'].replace('-','_')+'\n' for d in t['depends_on']) for t in TASKS)+'```\n\n## Candidate waves\n'+''.join(f'- Wave {i}: '+', '.join(w)+'\n' for i,w in enumerate(waves,1))+'\n## Integration policy\nOne coordinator owns state and integration. Each task starts from the latest integrated commit after all dependencies are DONE. Changes outside its allowlist block. A merge conflict is returned to the task author in its own branch; never auto-resolve semantically. Integration reruns gates and independent approvals on the merged content before publishing DONE. Reviews never approve a moving worktree.\n')
write('openspec/specs/README.md','# Accepted capabilities\n\nNo target capability is declared implemented at preparation time. Current target requirements live in the proposed changes. After all tasks for one change reach verified DONE, the integrator may run OpenSpec archive for that change and promote its accepted specs here.\n')
